"""WAL reconstruction is checked against transactions generated by SQLite itself."""
import hashlib
from pathlib import Path
import sqlite3
import struct
import tempfile
import unittest
from unittest.mock import patch

from extractor import artifact_containers as ac, sqlite_wal as wal
from extractor.store import Evidence
from tests.test_artifact_containers import STICKY, Containers


def captured_database():
    with tempfile.TemporaryDirectory() as directory:
        path = Path(directory) / 'notes.sqlite'
        db = sqlite3.connect(path)
        try:
            db.execute('PRAGMA journal_mode=WAL')
            db.execute('PRAGMA wal_autocheckpoint=0')
            db.executescript(STICKY)
            db.commit()
            db.execute('PRAGMA wal_checkpoint(TRUNCATE)')
            base = path.read_bytes()
            db.execute("INSERT INTO Note VALUES ('one', 'WAL-only note', 1, 2)")
            db.commit()
            return base, Path(str(path) + '-wal').read_bytes()
        finally:
            db.close()


def texts(data):
    with tempfile.TemporaryDirectory() as directory:
        path = Path(directory) / 'view.sqlite'
        path.write_bytes(data)
        db = sqlite3.connect(path.as_uri() + '?mode=ro&immutable=1', uri=True)
        try:
            return db.execute('SELECT Text FROM Note ORDER BY Id').fetchall()
        finally:
            db.close()


def native_wal_texts(base, log):
    with tempfile.TemporaryDirectory() as directory:
        path = Path(directory) / 'captured.sqlite'
        path.write_bytes(base)
        Path(str(path) + '-wal').write_bytes(log)
        db = sqlite3.connect(path.as_uri() + '?mode=ro', uri=True)
        try:
            return db.execute('SELECT Text FROM Note ORDER BY Id').fetchall()
        finally:
            db.close()


class CommittedWal(unittest.TestCase):
    def test_native_sqlite_commits_supply_missing_note_without_changing_sources(self):
        base, log = captured_database()
        before = base, log
        self.assertEqual(texts(base), [])
        view, details = wal.committed_view(base, log)
        self.assertEqual(texts(view), [('WAL-only note',)])
        self.assertEqual((base, log), before)
        self.assertEqual(details['sqlite_view'], 'committed_wal')
        self.assertGreater(details['sqlite_commit_frame'], 0)
        self.assertEqual(details['sqlite_base_sha256'], hashlib.sha256(base).hexdigest())
        self.assertEqual(details['sqlite_wal_sha256'], hashlib.sha256(log).hexdigest())

    def test_uncommitted_valid_frame_is_not_applied(self):
        base, log = captured_database()
        log = bytearray(log)
        page_size = struct.unpack_from('>I', log, 8)[0]
        endian = '<' if struct.unpack_from('>I', log)[0] == 0x377f0682 else '>'
        state = wal._checksum(log[:24], endian)
        for offset in range(32, len(log), page_size + 24):
            struct.pack_into('>I', log, offset + 4, 0)
            state = wal._checksum(log[offset + 24:offset + 24 + page_size], endian,
                                  wal._checksum(log[offset:offset + 8], endian, state))
            struct.pack_into('>II', log, offset + 16, *state)
        view, details = wal.committed_view(base, bytes(log))
        self.assertEqual(texts(view), [])
        self.assertEqual(details['sqlite_commit_frame'], 0)
        self.assertGreater(details['sqlite_uncommitted_frames'], 0)

    def test_bad_header_or_wrong_database_page_size_cannot_supply_a_view(self):
        base, log = captured_database()
        corrupt = bytearray(log)
        corrupt[24] ^= 1
        wrong_size = bytearray(base)
        wrong_size[16:18] = b'\x02\x00'
        for a, b in ((base, bytes(corrupt)), (bytes(wrong_size), log), (base, log[:10])):
            with self.assertRaises(ValueError):
                wal.committed_view(a, b)

    def test_stale_or_corrupt_tail_is_explicit_and_never_becomes_a_record(self):
        base, log = captured_database()
        for tail in (b'partial', log[32:]):
            view, details = wal.committed_view(base, log + tail)
            self.assertEqual(texts(view), [('WAL-only note',)])
            self.assertEqual(details['sqlite_ignored_tail_bytes'], len(tail))
            self.assertIsNotNone(details['sqlite_ignored_tail_reason'])
        corrupt = bytearray(log)
        corrupt[-1] ^= 1
        view, details = wal.committed_view(base, bytes(corrupt))
        self.assertEqual(texts(view), [])
        self.assertIn('checksum', details['sqlite_ignored_tail_reason'])

    def test_size_and_frame_limits(self):
        base, log = captured_database()
        with patch.object(wal, 'MAX_FRAMES', 0), self.assertRaises(ValueError):
            wal.committed_view(base, log)
        with patch.object(wal, 'MAX_BYTES', len(base) - 1), self.assertRaises(ValueError):
            wal.committed_view(base, log)

    def test_corrupt_tail_header_does_not_invalidate_a_prior_commit(self):
        base, log = captured_database()
        for field, value in ((0, 0), (0, 0xffffffff), (4, 0xffffffff)):
            tail = bytearray(log[32:])
            struct.pack_into('>I', tail, field, value)
            captured = log + tail
            view, details = wal.committed_view(base, bytes(captured))
            self.assertEqual(texts(view), native_wal_texts(base, bytes(captured)))
            self.assertEqual(texts(view), [('WAL-only note',)])
            self.assertIn('checksum', details['sqlite_ignored_tail_reason'])


class WalContainerIntegration(unittest.TestCase):
    setUp = Containers.setUp
    run_reader = Containers.run_reader
    attributes = Containers.attributes
    def test_adjacent_wal_changes_note_subject_and_retains_both_source_hashes(self):
        base, log = captured_database()
        path = 'C:/Users/Alex/AppData/Local/Packages/Microsoft.MicrosoftStickyNotes_test/LocalState/plum.sqlite'
        self.fs.add(path, data=base)
        self.fs.add(path + '-wal', data=log)
        rows = self.run_reader()
        texts_found = [row for row in self.attributes(rows) if row['prov']['attribute_role'] == 'sticky_notes.note.text']
        self.assertEqual(len(texts_found), 1)
        prov = texts_found[0]['prov']
        self.assertEqual(prov['sqlite_view'], 'committed_wal')
        self.assertEqual(prov['container_sha256'], hashlib.sha256(base).hexdigest())
        self.assertEqual(prov['sqlite_wal_sha256'], hashlib.sha256(log).hexdigest())
        self.assertTrue(prov['sqlite_wal_source_path'].endswith('plum.sqlite-wal'))
        self.assertEqual(prov['source_snapshot'], 'base-volume')
        subjects = [row['aux'] for row in rows if row['kind'] == 'attributeSubject']
        self.assertTrue(any('sqlite-base-and-wal' in subject for subject in subjects))

    def test_unrelated_or_redirected_sidecar_is_not_used(self):
        base, log = captured_database()
        path = 'C:/Users/Alex/AppData/Local/Packages/Microsoft.MicrosoftStickyNotes_test/LocalState/plum.sqlite'
        other = path.replace('/Alex/', '/Other/') + '-wal'
        self.fs.add(path, data=base)
        self.fs.add(other, data=log)
        rows = self.run_reader()
        self.assertFalse(any(row['prov']['attribute_role'] == 'sticky_notes.note.text' for row in rows))
        self.fs.add(path + '-wal', data=log, resolves_to=other)
        self.ev = Evidence()
        self.assertEqual(self.run_reader(), [])
        self.assertTrue(self.ev.problems)


if __name__ == '__main__':
    unittest.main()
